# InDesign Spread-to-Single Page Converter

Here's a comprehensive `.jsx` script that converts a spreads document into a single-page document while preserving margins, master pages, and element positioning:

```javascript
/*
 * Spread-to-Single Page Converter for Adobe InDesign
 * 
 * Converts a facing-pages (spreads) document into a single-page document
 * while preserving:
 *   - All margins (including inside/outside → left/right conversion)
 *   - Master page assignments
 *   - Element positioning relative to page bounds
 *   - Layer structure
 *   - All page items and their properties
 *
 * Usage: Open a facing-pages document and run this script.
 * A new single-page document will be created with all content preserved.
 *
 * Version: 1.0
 * Compatibility: InDesign CS6+, CC 2018+
 */

#target indesign

(function () {
    // ==================== CONFIGURATION ====================
    var CONFIG = {
        showProgressBar: true,
        closeOriginal: false,
        preserveGuides: true,
        preserveGrids: true
    };

    // ==================== MAIN ====================
    function main() {
        if (app.documents.length === 0) {
            alert("Please open a document first.", "No Document Open", false);
            return;
        }

        var srcDoc = app.activeDocument;

        if (!srcDoc.documentPreferences.facingPages) {
            alert("This document is already a single-page (non-facing) document.\nNo conversion needed.", "Already Single Page", false);
            return;
        }

        // Confirm with user
        var proceed = confirm(
            "This script will create a new single-page version of:\n\n" +
            "\"" + srcDoc.name + "\"\n\n" +
            "Pages: " + srcDoc.pages.length + "\n" +
            "Master Spreads: " + srcDoc.masterSpreads.length + "\n\n" +
            "The original document will remain unchanged.\nProceed?",
            false,
            "Spread to Single Page Converter"
        );

        if (!proceed) return;

        app.scriptPreferences.enableRedraw = false;
        app.scriptPreferences.userInteractionLevel = UserInteractionLevels.NEVER_INTERACT;

        var startTime = new Date().getTime();

        try {
            convertDocument(srcDoc);
            var elapsed = ((new Date().getTime() - startTime) / 1000).toFixed(1);
            alert("Conversion complete!\nTime: " + elapsed + " seconds.", "Success", false);
        } catch (e) {
            alert("Error during conversion:\n" + e.message + "\n\nLine: " + e.line, "Error", true);
        } finally {
            app.scriptPreferences.enableRedraw = true;
            app.scriptPreferences.userInteractionLevel = UserInteractionLevels.INTERACT_WITH_ALL;
        }
    }

    // ==================== CORE CONVERSION ====================
    function convertDocument(srcDoc) {
        // ---------- Step 1: Gather source document info ----------
        var srcDocPrefs = srcDoc.documentPreferences;
        var srcMarginPrefs = srcDoc.marginPreferences;
        var pageWidth = srcDocPrefs.pageWidth;
        var pageHeight = srcDocPrefs.pageHeight;

        // Store page data from source
        var pageDataList = collectPageData(srcDoc);
        var masterDataList = collectMasterData(srcDoc);

        // ---------- Step 2: Create new document ----------
        var dstDoc = app.documents.add(false); // false = don't show window yet

        // Copy document preferences
        with (dstDoc.documentPreferences) {
            facingPages = false;
            pageWidth = srcDocPrefs.pageWidth;
            pageHeight = srcDocPrefs.pageHeight;
            pagesPerDocument = 1; // We'll add pages later
            documentBleedTopOffset = srcDocPrefs.documentBleedTopOffset;
            documentBleedBottomOffset = srcDocPrefs.documentBleedBottomOffset;
            documentBleedInsideOrLeftOffset = srcDocPrefs.documentBleedInsideOrLeftOffset;
            documentBleedOutsideOrRightOffset = srcDocPrefs.documentBleedOutsideOrRightOffset;
            documentSlugUniformSize = srcDocPrefs.documentSlugUniformSize;
            slugTopOffset = srcDocPrefs.slugTopOffset;
            slugBottomOffset = srcDocPrefs.slugBottomOffset;
            slugInsideOrLeftOffset = srcDocPrefs.slugInsideOrLeftOffset;
            slugRightOrOutsideOffset = srcDocPrefs.slugRightOrOutsideOffset;
        }

        // Copy measurement units
        dstDoc.viewPreferences.horizontalMeasurementUnits = srcDoc.viewPreferences.horizontalMeasurementUnits;
        dstDoc.viewPreferences.verticalMeasurementUnits = srcDoc.viewPreferences.verticalMeasurementUnits;

        // Temporarily set to points for precision
        var origHUnits = app.activeDocument !== undefined ? srcDoc.viewPreferences.horizontalMeasurementUnits : MeasurementUnits.POINTS;
        var origVUnits = srcDoc.viewPreferences.verticalMeasurementUnits;
        srcDoc.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
        srcDoc.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;
        dstDoc.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
        dstDoc.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;

        // ---------- Step 3: Recreate layers ----------
        recreateLayers(srcDoc, dstDoc);

        // ---------- Step 4: Copy swatches, styles, etc. ----------
        copyDocumentResources(srcDoc, dstDoc);

        // ---------- Step 5: Recreate master pages ----------
        var masterMap = recreateMasterPages(srcDoc, dstDoc, masterDataList);

        // ---------- Step 6: Recreate document pages ----------
        recreateDocumentPages(srcDoc, dstDoc, pageDataList, masterMap);

        // ---------- Step 7: Clean up extra default page if needed ----------
        cleanupExtraPages(dstDoc, pageDataList.length);

        // Restore measurement units
        srcDoc.viewPreferences.horizontalMeasurementUnits = origHUnits;
        srcDoc.viewPreferences.verticalMeasurementUnits = origVUnits;
        dstDoc.viewPreferences.horizontalMeasurementUnits = origHUnits;
        dstDoc.viewPreferences.verticalMeasurementUnits = origVUnits;

        // Show the new document
        dstDoc.windows.add();
        app.activeDocument = dstDoc;

        return dstDoc;
    }

    // ==================== DATA COLLECTION ====================

    /**
     * Collect all page data from source document
     */
    function collectPageData(srcDoc) {
        var pages = srcDoc.pages;
        var dataList = [];

        for (var i = 0; i < pages.length; i++) {
            var page = pages[i];
            var isLeftPage = (page.side === PageSideOptions.LEFT_HAND);

            var data = {
                index: i,
                name: page.name,
                appliedMasterName: page.appliedMaster ? page.appliedMaster.name : null,
                appliedMasterPrefix: page.appliedMaster ? page.appliedMaster.namePrefix : null,
                isLeftPage: isLeftPage,
                // Margins: inside/outside need to be converted to left/right
                marginTop: page.marginPreferences.top,
                marginBottom: page.marginPreferences.bottom,
                marginLeft: isLeftPage ? page.marginPreferences.right : page.marginPreferences.left,
                marginRight: isLeftPage ? page.marginPreferences.left : page.marginPreferences.right,
                columnCount: page.marginPreferences.columnCount,
                columnGutter: page.marginPreferences.columnGutter,
                // Page bounds [y1, x1, y2, x2]
                bounds: page.bounds.slice(0)
            };

            dataList.push(data);
        }

        return dataList;
    }

    /**
     * Collect master page/spread data
     */
    function collectMasterData(srcDoc) {
        var masterSpreads = srcDoc.masterSpreads;
        var dataList = [];

        for (var i = 0; i < masterSpreads.length; i++) {
            var ms = masterSpreads[i];
            var masterPages = [];

            for (var j = 0; j < ms.pages.length; j++) {
                var mp = ms.pages[j];
                var isLeft = (mp.side === PageSideOptions.LEFT_HAND);

                masterPages.push({
                    index: j,
                    side: mp.side,
                    isLeftPage: isLeft,
                    marginTop: mp.marginPreferences.top,
                    marginBottom: mp.marginPreferences.bottom,
                    marginLeft: isLeft ? mp.marginPreferences.right : mp.marginPreferences.left,
                    marginRight: isLeft ? mp.marginPreferences.left : mp.marginPreferences.right,
                    columnCount: mp.marginPreferences.columnCount,
                    columnGutter: mp.marginPreferences.columnGutter,
                    bounds: mp.bounds.slice(0)
                });
            }

            dataList.push({
                name: ms.name,
                namePrefix: ms.namePrefix,
                baseName: ms.baseName,
                appliedMasterName: ms.appliedMaster ? ms.appliedMaster.name : null,
                pages: masterPages
            });
        }

        return dataList;
    }

    // ==================== LAYER RECREATION ====================

    function recreateLayers(srcDoc, dstDoc) {
        var srcLayers = srcDoc.layers;

        // Create layers in reverse order to maintain stacking
        for (var i = srcLayers.length - 1; i >= 0; i--) {
            var srcLayer = srcLayers[i];
            var dstLayer;

            // Check if this layer already exists (like the default "Layer 1")
            try {
                dstLayer = dstDoc.layers.itemByName(srcLayer.name);
                if (!dstLayer.isValid) throw "not found";
            } catch (e) {
                dstLayer = dstDoc.layers.add();
            }

            dstLayer.name = srcLayer.name;
            dstLayer.visible = srcLayer.visible;
            dstLayer.locked = false; // Unlock during conversion
            dstLayer.printable = srcLayer.printable;

            try {
                dstLayer.layerColor = srcLayer.layerColor;
            } catch (e) { }
        }

        // Remove any default layers that weren't in source
        for (var k = dstDoc.layers.length - 1; k >= 0; k--) {
            var dl = dstDoc.layers[k];
            var found = false;
            for (var m = 0; m < srcLayers.length; m++) {
                if (srcLayers[m].name === dl.name) {
                    found = true;
                    break;
                }
            }
            if (!found && dstDoc.layers.length > 1) {
                try {
                    dl.remove();
                } catch (e) { }
            }
        }
    }

    // ==================== RESOURCE COPYING ====================

    function copyDocumentResources(srcDoc, dstDoc) {
        // Copy paragraph styles
        copyStyles(srcDoc.paragraphStyles, dstDoc, "paragraphStyle");
        // Copy character styles
        copyStyles(srcDoc.characterStyles, dstDoc, "characterStyle");
        // Copy object styles
        copyStyles(srcDoc.objectStyles, dstDoc, "objectStyle");
        // Copy swatches
        copySwatches(srcDoc, dstDoc);
        // Copy table styles and cell styles
        try {
            copyStyles(srcDoc.tableStyles, dstDoc, "tableStyle");
            copyStyles(srcDoc.cellStyles, dstDoc, "cellStyle");
        } catch (e) { }
    }

    function copySwatches(srcDoc, dstDoc) {
        for (var i = 0; i < srcDoc.swatches.length; i++) {
            var sw = srcDoc.swatches[i];
            try {
                if (sw.name === "" || sw.name === "None" ||
                    sw.name === "Paper" || sw.name === "Black" ||
                    sw.name === "Registration") continue;

                var existing;
                try {
                    existing = dstDoc.swatches.itemByName(sw.name);
                    if (existing.isValid) continue;
                } catch (e) { }

                if (sw instanceof Color) {
                    var newColor = dstDoc.colors.add();
                    newColor.name = sw.name;
                    newColor.model = sw.model;
                    newColor.space = sw.space;
                    newColor.colorValue = sw.colorValue;
                }
            } catch (e) { }
        }
    }

    function copyStyles(srcStyles, dstDoc, styleType) {
        // This is a simplified approach; full style copying is done
        // implicitly when we duplicate page items
    }

    // ==================== MASTER PAGE RECREATION ====================

    function recreateMasterPages(srcDoc, dstDoc, masterDataList) {
        var masterMap = {}; // maps source master name -> destination master spread

        // First pass: create all master spreads
        for (var i = 0; i < masterDataList.length; i++) {
            var mData = masterDataList[i];
            var srcMasterSpread = srcDoc.masterSpreads.itemByName(mData.name);
            var srcMasterPages = mData.pages;

            // For each page in the source master spread, we create a separate
            // single-page master in the destination (if the master had 2 pages for a spread)
            for (var j = 0; j < srcMasterPages.length; j++) {
                var mpData = srcMasterPages[j];
                var suffix = srcMasterPages.length > 1 ? (j === 0 ? "_L" : "_R") : "";
                var newMasterPrefix = mData.namePrefix + (srcMasterPages.length > 1 ? (j === 0 ? "L" : "R") : "");

                // Ensure unique prefix (max 4 chars)
                if (newMasterPrefix.length > 4) {
                    newMasterPrefix = newMasterPrefix.substring(0, 4);
                }

                var newMasterName = newMasterPrefix + "-" + mData.baseName + suffix;
                var dstMaster;

                // Use existing default master or create new
                if (i === 0 && j === 0) {
                    // Try to use the first existing master
                    try {
                        dstMaster = dstDoc.masterSpreads[0];
                        dstMaster.namePrefix = newMasterPrefix;
                        dstMaster.baseName = mData.baseName + suffix;
                    } catch (e) {
                        dstMaster = dstDoc.masterSpreads.add();
